{"version":"2b1","blocks":[{"type":"text","text":"The dot product of two vectors is a scalar representing the product of their magnitudes and the cosine of the angle between them."},{"type":"ui","source":"root = Stack([definition,diagram,angleControl,output])

angle = 60
angleControl = Control("Angle (degrees)", 0, 180, [], $angle)

// Convert degrees to radians for cosine
radians = $angle * 3.14159 / 180

// Vector magnitudes fixed at 1 for simplicity
magA = 1
magB = 1

// Dot product formula
// dot = |A||B|cos(theta)
dotProduct = magA * magB * cos(radians)

// Projection of B onto A
projectionLength = magB * cos(radians)

// Orthogonal check
orthogonal = ($angle == 90) ? 1 : 0

// Negative projection check
negativeProjection = ($angle > 90) ? 1 : 0

// Text explanation
definition = Text("The dot product of two vectors A and B is |A||B|cos(\u03B8), where \u03B8 is the angle between them. It measures how much one vector extends in the direction of the other.")

// Diagram showing vectors and angle
// Vector A along x-axis from (50,90) to (150,90)
// Vector B rotates from (50,90) to (50 + magB*cos(radians)*100, 90 - magB*sin(radians)*100)

xB = 50 + magB * cos(radians) * 100

yB = 90 - magB * sin(radians) * 100

vectorA = path("M 50 90 L 150 90")
vectorB = path("M 50 90 L " + xB + " " + yB)
angleArc = path("M 80 90 A 30 30 0 0 1 " + (80 + 30 * cos(radians)) + " " + (90 - 30 * sin(radians)))

angleLabelX = 80 + 35 * cos(radians / 2)
angleLabelY = 90 - 35 * sin(radians / 2)

angleText = text(angleLabelX, angleLabelY, "\u03B8 = " + $angle + "\u00B0")

projectionLine = path("M 50 90 L " + (50 + projectionLength * 100) + " 90")

arrowA = group([vectorA])
arrowB = group([vectorB])
arc = group([angleArc, angleText])
proj = group([projectionLine])

// Compose graphic
diagram = Graphic("Vectors and Angle", [arrowA, arrowB, arc, proj])

// Output text metrics
output = Stack([
  Text("Dot product: " + dotProduct.toFixed(3)),
  Text("Projection length of B on A: " + projectionLength.toFixed(3)),
  Text(orthogonal == 1 ? "Vectors are orthogonal (dot product is zero)." : ""),
  Text(negativeProjection == 1 ? "Projection is negative: angle > 90°." : "")
])
","state":[{"name":"angle","value":60}]}]}

